import json,itertools
w=json.loads(context)
q=w['quotes']; skus=w['skus']; vendors={v['id']:v for v in w['vendors']}
opts=[]
for s,info in skus.items():
 opts.append([x for x in q if x['sku']==s and x['quality']=='approved' and info['demand']<=x['units']<=info['demand']+2 and x['arrival']<=info['deadline']])
best=None
for picks in itertools.product(*opts):
 bysku={x['sku']:x for x in picks}
 if any(x['needs_same_vendor_sku'] and bysku[x['needs_same_vendor_sku']]['vendor']!=x['vendor'] for x in picks): continue
 units={}; carbon=0; gross={}; skset={}
 for x in picks:
  v=x['vendor']; units[v]=units.get(v,0)+x['units']; carbon+=x['carbon']; gross[v]=gross.get(v,0)+x['units']*x['unit_cents']; skset.setdefault(v,set()).add(x['sku'])
 if carbon>w['carbon_cap'] or len(units)<3 or any(units[v]>vendors[v]['unit_cap'] for v in units): continue
 total=0
 for v,u in units.items():
  d=vendors[v]; g=gross[v]; disc=d['tier_bps'] if u>=d['tier_units'] else 0
  merch=(g*(10000-disc)+5000)//10000
  total+=merch+(0 if g>=d['free_shipping_gross'] else d['shipping_cents'])
  if len(skset[v])>=2 and merch>=d['rebate_merchandise_min']: total-=d['rebate_cents']
 if best is None or total<best[0]: best=(total,[x['id'] for x in picks])
print(FINAL(str(best[0])))
